SELECT *
FROM shopwizard.tOrdOrderQuotDetail

    AND QuotNo = #{pQuotNo}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderQuotDetail

    AND QuotNo = #{pQuotNo}
    AND QuotSeq = #{pQuotSeq}
    AND Keywrd = #{pKeywrd}
    AND Capa = #{pCapa}
    AND MatchUpriceCode = #{pMatchUpriceCode}
    AND OrderProdName = #{pOrderProdName}
